void handleRoutingData(uint64_t connId, RoutingData& routingData) {
    auto pipeline = getRoutingPipeline(connId);
    if (!pipeline) {
        LOG(INFO) << "Routing pipeline not found for connection ID: " << connId;
        return;
    }

    pipeline->pauseTransport();

    uint32_t acceptorId = std::hash<std::string>()(routingData.toString()) % NUM_ACCEPTORS;
    Acceptor* acceptor = getAcceptor(acceptorId);

    if (!acceptor) {
        LOG(ERROR) << "Failed to find acceptor for ID: " << acceptorId;
        return;
    }

    folly::fibers::runInMainLoop([=] {
        folly::EventBase* evb = acceptor->getEventBase();
        folly::AsyncSocket* socket = pipeline->getSocket();

        if (socket) {
            socket->attachEventBase(evb);
        }

        auto newPipeline = createPipeline(routingData);
        if (!newPipeline) {
            LOG(ERROR) << "Failed to create new pipeline for connection ID: " << connId;
            return;
        }

        acceptor->addServerConnection(connId, newPipeline);
        newPipeline->activateTransport();
        newPipeline->readBufferedBytes();
    });
}

void handleIncomingRoutingData(uint64_t connId, RoutingData& routingData) {
    auto pipeline = getRoutingPipeline(connId);
    if (!pipeline) {
        LOG(INFO) << "Routing pipeline not found for connection ID: " << connId;
        return;
    }

    pipeline->pauseTransport();

    size_t acceptorIndex = std::hash<RoutingData>()(routingData) % numAcceptors;
    Acceptor* acceptor = &acceptors[acceptorIndex];

    folly::fibers::runInMainLoop([=]() {
        folly::EventBase* eventBase = acceptor->getEventBase();
        folly::AsyncSocket::UniquePtr socket = pipeline->releaseSocket();

        socket->attachEventBase(eventBase);

        PipelineBuilder builder;
        builder.setRoutingData(routingData);
        auto newPipeline = builder.build();
        acceptor->addServerConnection(std::move(newPipeline));

        newPipeline->activateTransport();
        newPipeline->readBufferedBytes();
    });
}

void handleIncomingRoutingData(uint64_t connId, RoutingData& routingData) {
