    }

    pipeline->pauseTransport();

    size_t acceptorIndex = std::hash<RoutingData>{}(routingData) % kNumAcceptors;
    Acceptor* acceptor = &acceptors[acceptorIndex];

    folly::fibers::requestIODeviceFiberContext(acceptor->getEventBase()->getUnderlyingEventBase()->loop());

    folly::AsyncSocket::UniquePtr socket(acceptor->getSocket());
    socket->attachEventBase(acceptor->getEventBase());

    auto newPipeline = createPipelineWithRoutingData(routingData);
    acceptor->addServerConnection(connId, std::move(socket), std::move(newPipeline));

    newPipeline->activateTransport();
    newPipeline->readBufferedBytes();
}

void handleRoutingData(uint64_t connId, RoutingData& routingData) {
